"""Generate the bounded TanStack report from pinned, SHA-verified evidence.

Only compact provenance/summary data and maintained HTML live in Labs. Acquisition
is an explicit maintenance operation; normal Nift builds never fetch evidence.
"""
from pathlib import Path
import json
import statistics
from html import escape
from evidence_sources import data_root, sources, url

ROOT = Path(__file__).resolve().parents[1]
PREFIX = 'content/sites/tanstack/data'
DATA = data_root(PREFIX)
REWRITE_PIN = 'https://github.com/nift-experiments/tanstack-rewrite/blob/4df533907b5b82ff842f7a58d2cdf13dea7f7735/'
rewrite = json.loads((data_root('content/sites/tanstack/rewrite-data') / 'focused-performance-gate.json').read_text())
assert rewrite['implementationRevision'] == 'a68401f' or rewrite['implementationRevision'].startswith('a68401f')
rr = rewrite['results']
assert [round(rr[k]['wallSeconds']['median'],2) for k in rr] == [192.28,10.36,37.50,163.69]
def load(name): return json.loads((DATA / name).read_text())
summary = load('architecture-summary.json')
samples = load('architecture-samples.json')
components = load('components.json')
repro = load('reproduction.json')
snapshot = load('snapshot-rejection.json')
article = load('article-rejection.json')
history = load('historical-t10.json')
assert len(samples) == 80 and len(summary) == 16 and all(x['samples'] == 5 for x in summary)
assert len(history) == 45 and all(x['samples'] == 5 for x in history)
assert repro['expanded_browser']['states'] == 333 and repro['expanded_browser']['page_errors'] == 0
assert repro['equality']['normal_and_forced_equal_to_independent_fresh'] and repro['equality']['publication_files'] == 24224
assert snapshot['status'] == 'rejected-parity-loss' and not snapshot['timings_eligible']
assert article['status'] == 'rejected-as-authoritative-maintained-HTML-model' and not article['timing_eligible']
assert article['html_edit_visible_in_real_server_article'] and not article['html_edit_survives_hydration']
lookup = {(r['implementation'], r['workload']): r for r in summary}
for row in summary:
    cohort = [r for r in samples if (r['implementation'], r['workload']) == (row['implementation'], row['workload'])]
    assert len(cohort) == 5
    for metric in ('wall_seconds', 'maximum_individual_process_rss_kib', 'sampled_descendant_tree_peak_rss_kib'):
        assert row[metric] == {'median': statistics.median(r[metric] for r in cohort), 'min': min(r[metric] for r in cohort), 'max': max(r[metric] for r in cohort)}
MODELS = [('faithful-agent', 'A / faithful Start + Vite'), ('tanstack-agent', 'B / Start + Rsbuild')]
WORK = [('full', 'Warm full'), ('fresh', 'Fresh application state'), ('unchanged', 'Unchanged command'), ('body-1', 'One document'), ('shared-shell', 'Shared shell'), ('island', 'Browser component'), ('route-rename', 'Route rename'), ('route-delete', 'Route delete')]
assert lookup['faithful-agent', 'full']['wall_seconds']['median'] == 32.94
assert lookup['tanstack-agent', 'full']['wall_seconds']['median'] == 41.55
def evidence(name): return url(sources()['files'][PREFIX + '/' + name])
PIN = 'https://github.com/nift-experiments/tanstack-agent/blob/8bd68069410f984a5949e7fa0e629b6084c1caee/'
AUTH = 'https://github.com/nift-experiments/tanstack/tree/7af3af0141e09248dacfc11f722c495abadd96a4'
AGENT = 'https://github.com/nift-experiments/tanstack-agent/tree/8bd68069410f984a5949e7fa0e629b6084c1caee'
UPSTREAM = 'https://github.com/TanStack/tanstack.com/tree/862ccc3d191818320c3e6d217542883f80cb907a'
def table(head, rows):
    return '<div class="table-wrap" role="region" tabindex="0" aria-label="Measurements table; scroll horizontally on narrow screens"><table><thead><tr>' + ''.join('<th scope="col">'+h+'</th>' for h in head) + '</tr></thead><tbody>' + ''.join('<tr>'+''.join('<th scope="row">'+str(c)+'</th>' if i == 0 else '<td>'+str(c)+'</td>' for i,c in enumerate(row))+'</tr>' for row in rows) + '</tbody></table></div>'
def val(row, metric='wall_seconds', mib=False):
    d=row[metric]; scale=1024 if mib else 1; precision=1 if mib else 2
    return f'<strong>{d["median"]/scale:,.{precision}f}</strong><small>{d["min"]/scale:,.{precision}f}–{d["max"]/scale:,.{precision}f}</small>'
def section(n, id, title, body):
    return f'<section class="chapter" id="{id}"><div class="chapter-label"><span>{n:02}</span><p>{id.replace("-"," ")}</p></div><div class="chapter-body"><h2>{title}</h2>{body}</div></section>'
def rails(title, metric, axis, unit, workloads, mib=False):
    out=f'<figure class="measurement"><figcaption>{title}</figcaption><div class="axis"><span>0</span><span>{axis/2:,.0f}</span><span>{axis:,.0f} {unit}</span></div>'
    for work,label in workloads:
        out+=f'<div class="trace-group"><h4>{label}</h4>'
        for impl,name in MODELS:
            d=lookup[impl,work][metric]; v=d['median']/(1024 if mib else 1); dp=1 if mib else 2
            out+=f'<div class="measure-line {"alternate" if impl=="tanstack-agent" else "faithful"}"><div class="measure-label"><span>{name}</span><b>{v:,.{dp}f} {unit}</b></div><div class="rail" aria-hidden="true"><i style="width:{100*v/axis:.4f}%"></i></div></div>'
        out+='</div>'
    return out+'</figure>'

parts=['''<header class="mast"><a class="brand" href="@path('/')">NIFT LABS<span>Case file / 08</span></a><nav aria-label="Report navigation"><a href="#boundary">Boundary</a><a href="#measurements">Measurements</a><a href="#rewrite">Rewrite</a><a href="#evidence">Evidence</a></nav><a class="all" href="@path('sites/')">All experiments ↗</a></header><main id="main">
<section class="hero"><div class="hero-copy"><p class="eyebrow">Architecture investigation / 08 / October 2026</p><h1>TanStack.com<span>Two attempts.<br>Closed.</span></h1><p class="lead">Exploring where Nift fits alongside TanStack.<br>Not replacing the entire ecosystem.</p><p>We wanted Nift to own publication and build work while keeping the TanStack libraries and application behavior that make sense to retain. The faithful migration retained too much expensive Start/runtime work. A subsequent rewrite improved separation, but its chosen corpus-generation and dependency architecture failed the performance gate. This was never intended as “replace TanStack with Nift.”</p><p class="qualification">Independent research. No TanStack affiliation or endorsement. No Nift core changes.</p></div><figure class="boundary-console"><figcaption>Two attempts / distinct termination reasons</figcaption><div class="console-domain publication-domain"><span class="domain-id">01 / MIGRATION</span><h2>Retained<br>runtime</h2><div class="signal-wire"><i></i><i></i><i></i></div><p>Start · browser · Worker</p><strong>Not enough dominant work moved</strong></div><div class="console-boundary"><span>NO COMPELLING ARCHITECTURE</span><b aria-hidden="true">↯</b></div><div class="console-domain runtime-domain"><span class="domain-id">02 / REWRITE</span><h2>Generated<br>corpus graph</h2><div class="signal-wire"><i></i><i></i><i></i></div><p>Preparation · contexts · dependencies</p><strong>Chosen representation too expensive</strong></div><div class="console-footer"><span>PARITY EVIDENCE PRESERVED</span><span>BOTH ATTEMPTS CLOSED</span></div></figure><aside class="finding" aria-label="Current experiment status"><p class="eyebrow">Disposition / final</p><div class="status-block"><span>Migration result</span><strong>No compelling <br>migration found</strong><p>Unsuccessful / poor architectural fit</p></div><div class="status-block next"><span>Rewrite result</span><strong>Unsuccessful / closed</strong><p>Generated corpus / preparation too expensive.</p></div><div class="boundary-mark" aria-hidden="true"><span>NIFT-OWNED</span><i></i><span>RETAINED RUNTIME</span></div></aside></section>
<div class="finding-line"><span>Finding 01</span><p>Migration: retained runtime too dominant. Rewrite: the particular generated corpus and dependency graph were too expensive. Neither establishes a general Nift limitation.</p></div>''']
parts.append(section(1,'boundary','Phase 1 — faithful migration.','''<p>The target was the full public application, not a static imitation of its docs. Request-specific sessions, Router/Query behavior, real charts, search, chat/API boundaries and generated products remained part of the contract.</p><figure class="architecture-map"><figcaption>Build responsibility and request-time ownership</figcaption><div class="architecture-columns"><div class="architecture-path"><h3>Upstream</h3><p>Original content inputs</p><span class="connector" aria-hidden="true">↓</span><p>TanStack Start / Vite</p><span class="connector" aria-hidden="true">↓</span><p>React / Redact / Router / Query<br>Cloudflare application services</p><strong>Start owns request-time HTML</strong></div><div class="architecture-path"><h3>A / faithful Nift</h3><p class="nift-node">Nift publication<br>Docs + projections + assets</p><span class="connector" aria-hidden="true">↓</span><p>Retained Start / Vite build</p><span class="connector" aria-hidden="true">↓</span><p>Original browser + Worker runtime</p><strong>Dominant build cost remains</strong></div><div class="architecture-path"><h3>B / alternate engine</h3><p class="nift-node">Same Nift publication</p><span class="connector" aria-hidden="true">↓</span><p>Official Start / Rsbuild adapter</p><span class="connector" aria-hidden="true">↓</span><p>Original browser + Worker runtime</p><strong>Lower RSS / slower warm full</strong></div></div><p class="figure-note">B changes the compiler engine. It does not transfer request-time page or docs rendering to Nift.</p></figure><div class="source-models"><div><h3>Nift <code>tanstack</code><small>Authored-source / faithful</small></h3><p>Maintained Markdown, frontmatter and structured references derive document AST, raw/download views and metadata. Nift composes prepared inputs; Start renders the public application.</p></div><div><h3>Nift <code>tanstack-agent</code><small>Rendered-source / agent-primary</small></h3><p>Maintained TanStack document AST envelopes with explicit original/download projections. This is a hybrid runtime-consumed representation, <strong>not whole maintained HTML</strong>. More restructuring freedom did not relax parity.</p></div></div><p>React, Router, Query, Table and AI remain product dependencies where used. Start also supplies server functions, serialization and hydration. Vite is build tooling, not a required runtime library. Redact aliases, Tailwind, Content Collections, Sentry runtime and Cloudflare bindings remain explicit integration responsibilities.</p>'''))
parts.append(section(2,'paths','Five branches. No forced winner.','''<ol class="branches"><li class="accepted"><span class="branch-code">A</span><div><h3>Faithful Start / Vite</h3><p>Accepted behavior. Preserved as the conservative default, but not compelling as a complete application migration.</p></div><span class="path-state">Preserved</span></li><li class="investigated"><span class="branch-code">B</span><div><h3>Official Start / Rsbuild adapter</h3><p>Executable alternate engine. Memory falls; warm full publication slows. Start stays in charge of SSR.</p></div><span class="path-state">Tradeoff</span></li><li class="terminated"><span class="branch-code">C1</span><div><h3>Whole-page snapshot + real backend</h3><p>Required request-specific session behavior is frozen in the published HTML.</p></div><span class="path-state">Rejected</span></li><li class="terminated"><span class="branch-code">C2</span><div><h3>Maintained article HTML bridge</h3><p>HTML-only edits appear on the server, then disappear when the original AST-based components mount.</p></div><span class="path-state">Rejected</span></li><li class="terminated"><span class="branch-code">R</span><div><h3>Nift-first rewrite</h3><p>Separation worked. The chosen generated publication graph failed its viability gate.</p></div><span class="path-state">Closed</span></li></ol><p class="qualification">Plain esbuild also failed with 204 browser-graph compilation errors: server-only imports and framework transformations cannot simply be skipped. Failed compilation and rejected C branches receive no successful-build timing.</p>'''))
parts.append(section(3,'parity','The migration failure was architectural.','''<p class="lead">Preserving behavior worked. Finding a worthwhile new ownership boundary did not.</p><div class="proof-strip"><div><strong>7,527</strong><span>document contracts / 25 roots</span></div><div><strong>333</strong><span>browser states / no page errors</span></div><div><strong>24,224</strong><span>files / normal–forced byte equality</span></div></div><p>The Rsbuild candidate reproduced with independently installed frozen runtime dependencies and a separately locked adapter toolchain. All 244 maintained static assets match byte-for-byte. Required type, lint, unit, chat and desktop suites pass, with one existing desktop skip.</p><p>Real local Worker proofs preserve API boundaries, generated output, byte-identical request-time OG PNGs, fresh sessions, Markdown negotiation, mobile navigation, search navigation and the catalog renderer. No handler was replaced with a static success stub.</p><p class="qualification">Browser semantics and interaction checks are not universal pixel identity. API/service proofs use controlled fixtures and unauthenticated boundaries; private live authenticated integrations are not certified. Hosted Algolia remains; there is no omitted local search-index build.</p>'''))
hist={(r['implementation'],r['workload']):r for r in history}
parts.append(section(4,'earlier-result','Keep the first faithful result visible.','''<p>The preserved T10 campaign has 225 observations: 15 cases × three implementations × five samples. It predates the T11 cache work and the T12 architecture comparison below. These cohorts must not be spliced into a single ranking.</p>'''+table(['T10 / seconds, median [min–max]','Upstream Start / Vite','Nift authored-source','Nift rendered-source'],[[label]+[val(hist[m,w]) for m in ['upstream','tanstack','tanstack-agent']] for w,label in [('full','Warm full'),('fresh','Fresh application state'),('unchanged','Unchanged command'),('body-1','One document'),('route-rename','Route rename'),('route-delete','Route delete')]])+'''<p>Unchanged and rename/delete publication improved; ordinary upstream document edits remained competitive or faster. Upstream changed-doc timing is its native ready-input R2 refresh, whereas Nift measures complete document/assets publication. This is production work, not development-server/HMR latency. Fresh-state cleanup placement also differs; the original report keeps those boundaries visible.</p><p class="qualification">The T11 replacement 225-row campaign is still pending. Its optimized authored timings are not inferred from the agent-only T12 results.</p>'''))
parts.append(section(5,'measurements','Less memory. More time. Still Start.','''<p>The bounded T12 investigation compares two <strong>agent-source</strong> pipelines: faithful Start/Vite and official Start/Rsbuild. It is not a comparison of authored versus rendered source.</p><div class="tradeoff">'''+rails('Warm full / complete publication','wall_seconds',50,'s',[('full','Time')])+rails('Warm full / maximum individual process RSS','maximum_individual_process_rss_kib',5000,'MiB',[('full','Memory')],True)+'''</div><p class="tradeoff-caption">Rsbuild saves memory here, but loses warm-full time. Neither removes the dominant runtime build. This is the observed tradeoff in this application, not a judgement about Rsbuild generally.</p>'''+table(['T12 / seconds, median [min–max]']+[n for _,n in MODELS],[[label]+[val(lookup[m,w]) for m,_ in MODELS] for w,label in WORK])+'''<p class="qualification">80 accepted samples: eight workloads × two variants × five serialized repetitions. Clock includes required browser <strong>and</strong> backend bundling, content, assets and Worker configuration. No separate service build is hidden. Fresh-state ranges overlap substantially; no fresh-build winner is claimed. Installed dependencies and acquisition are excluded; fresh application state does not mean cold OS caches. Fixed cohort order and shared-host load limit small-difference claims.</p>'''))
parts.append(section(6,'incremental-memory','The boundary is visible in iteration memory.','''<p>Document-only edits and lifecycle updates reuse verified runtime bundles. Shared shell and browser-component edits cross the retained compiler boundary. Peak memory rises with that boundary, not with Nift simply rendering one page.</p>'''+rails('Changed-input / maximum individual process RSS','maximum_individual_process_rss_kib',5000,'MiB',WORK[2:],True)+table(['T12 / MiB, median [min–max]','A individual process','B individual process','A sampled tree','B sampled tree'],[[label]+[val(lookup[m,w],metric,True) for metric in ['maximum_individual_process_rss_kib','sampled_descendant_tree_peak_rss_kib'] for m,_ in MODELS] for w,label in WORK])+'''<p class="qualification">Individual RSS is GNU time maximum process/phase usage, not aggregate memory. Tree RSS is a nominal 50ms PID-deduplicated descendant sum: it can miss short peaks and double-count shared mappings. It is not PSS. Both scopes and observed ranges remain separate; neither is a dedicated-machine memory guarantee.</p>'''))
fullcomp={r['implementation']:r['median_seconds'] for r in components if r['workload']=='full'}
parts.append(section(7,'dominant-cost','Nift did not consume 4.4 GiB to render pages.','''<div class="ownership-layers"><div class="owned-layer"><span>Nift-owned work</span><h3>Prepared docs / projections / composition</h3><p>Useful publication work. Not the dominant full-build cost.</p></div><div class="boundary-seam"><span>Migration boundary</span></div><div class="retained-layer"><span>Retained application compiler</span><h3>Start + browser/server emission</h3><p>Expensive runtime build responsibility remains here.</p></div></div>'''+table(['Warm full component / median seconds','A / Start + Vite','B / Start + Rsbuild'],[[name]+[f'{fullcomp[m][key if m=="faithful-agent" or key!="retained_vite_build" else "retained_rsbuild_build"]:.2f}' for m,_ in MODELS] for key,name in [('retained_vite_build','Retained engine, both environments'),('content_publication','Complete content stage'),('nift_composition','Nift composition within content stage'),('retained_asset_publication','Retained asset publication'),('publisher_compilation','Publisher compilation')]])+'''<p>Vite's approximately 4.4 GiB process peak occurs around server emission. V8 live heap was much smaller at the sampled RSS peak, and heap caps did not materially remove that RSS peak. This does not establish a native allocator cause; overlapping diagnostic heap trials are not accepted timing comparisons. Rsbuild's own Node compiler becomes dominant around SSR completion.</p><blockquote>This does not show that Nift itself has the same build cost or memory profile as TanStack Start. It shows that the migration retained too much of the existing runtime/build architecture for Nift to meaningfully change the dominant cost.</blockquote><p class="qualification">Nift composition is a nested component, not an additional cost to sum on top of content publication. Median components need not sum to a median total. These are complete orchestrated pipelines, not native <code>@markup</code> performance.</p>'''))
parts.append(section(8,'rejected-splits','The deeper branches ended at real contracts.','''<div class="rejection"><span class="termination" aria-hidden="true">×</span><div><p class="eyebrow">C1 / branch terminated</p><h3>A live backend cannot unfreeze a static shell.</h3><p>Original backend forwarding worked and its request seed rotated. The Nift-published whole page retained the old seed. Required partner/session behavior therefore failed. Static output alone was not a faithful substitute.</p></div></div><div class="rejection"><span class="termination" aria-hidden="true">×</span><div><p class="eyebrow">C2 / branch terminated</p><h3>Server-visible HTML was not the maintained authority.</h3><p>Three real pages covered ordinary content, a table and tabs/code. Twelve scoped browser states initially matched. An HTML-only edit published normally and appeared in SSR, then vanished after the original interactive components mounted from their unchanged AST. A shadow AST would require coordinated maintenance; a clean HTML authority needs a different component/island boundary.</p></div></div><p>We stopped rather than weaken parity, fake dynamic functionality or reimplement substantial parts of Start. These bounded failures do not prove that every possible service/island design is impossible.</p>'''))
parts.append(section(9,'what-worked','Useful work. An unconvincing migration.','''<ul class="findings-list"><li><strong>Verified bundle reuse</strong><span>Unchanged publication avoids redundant application compilation.</span></li><li><strong>Docs stay outside the heavy build</strong><span>Normal document edits reuse the unchanged browser/backend bundles.</span></li><li><strong>Correct publication and retirement</strong><span>Custom publisher, explicit dependencies, rename/delete handling and cache repair preserve outputs.</span></li><li><strong>Independent recomputation</strong><span>Normal and forced output equality survives a fresh dependency install.</span></li></ul><p>Those gains matter, but they do not make the entire application migration worthwhile. Full/fresh build cost, retained peak memory and compiler integration complexity remain. The source cache improvements do not transfer request-time HTML ownership.</p><h3>Why publish a negative result?</h3><p>Labs records what actually happens, including targets where migration is not compelling. Publishing the failed boundary makes the successful experiments more credible and keeps architecture fit separate from benchmark cherry-picking.</p>'''))
assert round(rr['warm-full']['maximumIndividualProcessPhaseRssMiB']['median'],1) == 2378.9
assert round(rr['warm-full']['sampledDescendantRssMiB']['median'],1) == 5364.9
assert [round(rr['warm-full']['phaseWallCosts'][k]['medianSeconds'],2) for k in ['frontend-producer','corpus-preparation']] == [26.91,36.10]
assert round(rr['warm-full']['niftExclusiveWallSeconds']['median'],2) == 129.12
def rewrite_rails(title, values, axis, unit):
    return '<figure class="measurement"><figcaption>'+title+'</figcaption><div class="axis"><span>0</span><span>'+str(axis/2)+'</span><span>'+str(axis)+' '+unit+'</span></div>'+''.join('<div class="measure-line"><div class="measure-label"><span>'+label+'</span><b>'+f'{v:,.2f}'+' '+unit+'</b></div><div class="rail" aria-hidden="true"><i style="width:'+str(100*v/axis)+'%"></i></div></div>' for label,v in values)+'</figure>'
parts.append(section(10,'rewrite','Phase 2 — Nift-first rewrite. Closed.','''<p class="lead">Initialized with <code>nift init --rewrite</code>, this attempt moved static HTML and publication onto Nift while retaining useful TanStack components, frontend islands and explicit backend services.</p><div class="rewrite-plan"><div class="rewrite-state"><span>Attempt 1 / terminated</span><strong>Migration<br>Retained runtime dominates</strong></div><span class="rewrite-arrow" aria-hidden="true">→</span><div class="rewrite-state"><span>Attempt 2 / terminated</span><strong>Rewrite<br>Generated corpus too costly</strong></div></div><p>Nift-owned HTML remained authoritative and retained runtime pieces continued to work. Exact design and behavior parity was pursued. The resulting implementation still failed its agreed viability gate after one bounded performance pass; the experiment closed without further rescue or parity polishing.</p><p class="qualification"><strong>Workload distinction:</strong> the rewrite emits 14,247 complete static pages plus 14,107 fragments, while upstream and the faithful migration serve docs dynamically. These differ in responsibility. That difference does not waive the agreed viability gate.</p>'''+rewrite_rails('Accepted full-publication medians / separate cohorts and responsibilities',[('Upstream / accepted T10',31.22),('Faithful migration / accepted T10',32.42),('Rewrite / three-sample decision gate',192.28)],200,'s')+table(['Rewrite decision gate / seconds','Median','Observed range'],[[label,f"{rr[k]['wallSeconds']['median']:.2f}",'–'.join(f'{v:.2f}' for v in rr[k]['wallSeconds']['range'])] for k,label in [('warm-full','Warm full'),('unchanged','Unchanged'),('docs-edit','Docs edit'),('frontend-edit','Frontend edit')]])+'''<p class="qualification">Three serialized samples per scenario; diagnostic viability evidence, not a final five-sample acceptance campaign. Accepted upstream/migration measurements were not rerun. Fresh-state, shared-layout and backend-only cases were not rerun after the hard full-build gate failed.</p>'''))
parts.append(section(11,'rewrite-memory','Two memory scopes. Keep them separate.',rewrite_rails('Rewrite full / maximum individual process or phase RSS',[('Maximum individual process / phase',2378.9)],6000,'MiB')+rewrite_rails('Rewrite full / sampled descendant tree RSS',[('Sampled tree / separate scope',5364.9)],6000,'MiB')+rewrite_rails('Rewrite incremental / maximum individual process or phase RSS',[(label,rr[k]['maximumIndividualProcessPhaseRssMiB']['median']) for k,label in [('unchanged','Unchanged'),('docs-edit','Docs edit'),('frontend-edit','Frontend edit')]],6000,'MiB')+'''<p>These are different metrics and should not be read interchangeably. Individual-process RSS improved substantially from the earlier rewrite, but sampled tree memory remained high. The bounded pass changed warm full from 232.01s to 192.28s, docs edits from 63.40s to 37.50s and frontend edits from 482.51s to 163.69s. Unchanged publication regressed from 5.79s to 10.36s.</p><p class="qualification">GNU time maximum process/phase RSS is not aggregate memory. Sampled descendant RSS can double-count shared mappings and miss short peaks; it is not PSS. Persistent preview/database services are excluded.</p>'''))
parts.append(section(12,'rewrite-proofs','What worked. What remained too expensive.','''<div class="proof-strip"><div><strong>96/96</strong><span>semantic states passed</span></div><div><strong>91/96</strong><span>exact RGB states passed</span></div><div><strong>14,247</strong><span>complete static pages</span></div></div><ul class="findings-list"><li><strong>Five thin viewport differences</strong><span>Preserved as open visual items, not final parity acceptance.</span></li><li><strong>14,107 docs outputs</strong><span>Frontend edits rerendered zero docs; docs edits affected six docs. Browser/backend builds stayed off for docs edits.</span></li><li><strong>Subsystem separation</strong><span>Nift-owned HTML, selective retained runtime pieces and frontend/backend boundaries worked.</span></li><li><strong>4.72 GB retired caches</strong><span>Mapped repeated uncompressed shell caches were removed after equivalence checks.</span></li></ul>'''+table(['Warm-full phase / median seconds','Cost'],[['Frontend producer','26.91'],['Corpus preparation','36.10'],['Exclusive Nift work','129.12']])+'''<p class="qualification">Exclusive Nift work includes dependency processing, caching, composition, output and orchestration for this generated graph. It is not a measure of ordinary Nift template rendering or built-in Markdown performance. Producer phases overlap; component medians need not sum to a median total.</p><p>The rewrite successfully separated Nift-owned publication from retained runtime services, but its generated corpus representation and preparation pipeline were too expensive to justify. Whole-corpus page-context traversal/serialization persisted, and fine-grained shared imports increased dependency/composition work.</p><blockquote>The chosen corpus-generation and dependency architecture failed. This does not establish that a simpler Nift template/content architecture would have the same cost.</blockquote><p>No general Nift core ceiling was demonstrated. A simpler shared-template approach was not disproved; the experiment stopped because its one authorized rescue pass missed the agreed gate.</p>'''))
parts.append(section(13,'lessons','Guidance for the next rewrite, elsewhere.','''<p>Preserving too much incumbent architecture can obscure Nift’s benefits; architectural freedom alone does not guarantee a better result. Staticizing a large dynamic-docs surface introduces real responsibility and cost.</p><ul class="criteria"><li>Require corpus-scale generation and usable publication coverage early, rather than isolated parity proofs.</li><li>Run a complete-workload performance viability gate before extended parity refinement.</li><li>Require explicit frontend, backend and content invalidation boundaries.</li><li>Use dependency-aware preparation and a bounded shared-chrome strategy.</li><li>Make <code>\\@input</code>, <code>\\@content</code> and <code>\\@path</code> guidance prominent; use <code>\\@path</code> for internal links, images, video and other local publication references.</li><li>Prefer ordinary shared templates and small per-page content/metadata when they meet the contract; retain islands where their functionality earns the complexity.</li></ul><p>Bounded shared templates, grouped immutable chrome data, avoiding unchanged context reserialization and profiling large dependency graphs remain separate Nift/tooling research candidates. They do not reopen this experiment.</p>'''))

links=[('Rewrite closeout',REWRITE_PIN+'investigation/STATUS.md'),('Rewrite accepted source checkpoint',REWRITE_PIN.replace('/blob/','/tree/')),('Focused three-sample performance gate',REWRITE_PIN+'evidence/r3/focused-performance-gate.json'),('Rewrite paired browser/pixel evidence',REWRITE_PIN+'evidence/r3/paired-browser-pixels.json'),('Complete composed-shell equivalence',REWRITE_PIN+'evidence/r3/shared-markup-verification.json'),('Pinned upstream application',UPSTREAM),('Nift tanstack / authored-source repository',AUTH),('Nift tanstack-agent / rendered-source repository',AGENT),('T12 architectural ownership report',PIN+'investigation/T12-ARCHITECTURE.md'),('T12 raw 80-sample dataset',evidence('architecture-samples.json')),('T12 summaries and ranges',evidence('architecture-summary.json')),('Component costs',evidence('components.json')),('Independent reproduction receipt',evidence('reproduction.json')),('Whole-page rejection',evidence('snapshot-rejection.json')),('HTML authority rejection',evidence('article-rejection.json')),('Preserved T10 / 225-row summary',evidence('historical-t10.json')),('Original T10 intermediate report',PIN+'INTERMEDIATE-REPORT.md'),('Heap/cache optimization qualifications',PIN+'investigation/T11-OPTIMIZATION.md'),('Prototype code and dependency inventory',PIN.replace('/blob/','/tree/')+'investigation/t12-prototypes')]
parts.append(section(14,'evidence','Inspect the result. Keep the boundaries.','''<p>This page closes <strong>both the migration and rewrite</strong> as unsuccessful. Rewrite measurements use Nift 4.10.0 and Node 25.9.0; the migration toolchain below belongs to its separate cohort. It uses the accepted T12 investigation and keeps T10 historical evidence separate. The broader T11 replacement 225-row campaign is not complete and is not used to overstate the conclusion. Repository checkpoints were clean and synchronized at publication; frozen links preserve the exact source/evidence state.</p><p>Toolchain: Nift 4.9.0, Node 25.9.0 and pnpm 11.1.0. Raw logs, environment/sampler records, restoration receipts and rejected experiments remain in the experiment repositories. Labs stores compact rendering summaries and displayed assets only.</p><ul class="evidence-links">'''+''.join(f'<li><a href="{escape(href)}">{escape(label)} <span aria-hidden="true">↗</span></a></li>' for label,href in links)+'''</ul>'''))
parts.append(section(15,'conclusion','Neither tested architecture is recommended.','''<p class="lead">We would not recommend either tested TanStack.com architecture.</p><div class="rejection"><span class="termination" aria-hidden="true">×</span><div><h3>Migration</h3><p>Too much expensive incumbent runtime/build architecture remained; Nift did not take ownership of enough dominant work.</p></div></div><div class="rejection"><span class="termination" aria-hidden="true">×</span><div><h3>Rewrite</h3><p>Separation improved, but the particular generated corpus representation, preparation pipeline and dependency graph built for this rewrite remained too expensive.</p></div></div><p>This establishes neither that Nift is generally unsuitable for TanStack projects nor that ordinary shared templates and content would incur the same cost. It establishes that neither tested implementation was compelling for this application and workload.</p><p>Labs publishes unsuccessful experiments as well as successful ones. The purpose is to learn where Nift is useful, not manufacture a win on every target.</p><div class="closing-status"><span>Migration: unsuccessful</span><span>Rewrite: unsuccessful / experiment closed</span></div>'''))
parts.append('</main><footer class="footer"><a href="@path(\'/\')">Nift Labs</a><p>Preserve parity. Measure honestly. Publish the boundary.</p><a href="@path(\'sites/\')">Explore the experiments ↗</a></footer>')
destination=ROOT/'content/sites/tanstack/index.html'
destination.write_text('\n'.join(parts)+'\n')
